    platforms: [.macOS(.v13)],
    targets: [
        .target(
            name: "ObjCExceptionTrap",
            path: "Sources/ObjCExceptionTrap"
        ),
        .executableTarget(
            name: "LaughCounter",
            dependencies: ["ObjCExceptionTrap"],
            path: "Sources/LaughCounter"
        )
    ]
)
