import AVFoundation
import CoreMedia
import SoundAnalysis

/// Laughter detection using Apple's **built-in** sound classifier (no model to
/// download, no third-party ML). For each analysed window it reports a full
/// `LaughObservation`: the laughter confidence and which laugh class won, the
/// strongest TV-context class (for de-conflicting TV audio), a few top competing
/// classes (for debugging false positives), and the window's *real* audio timing.
///
/// We match several related laugh class identifiers (laughter, giggle, chuckle …)
/// so we don't overfit to a single style of laugh.
final class LaughDetector: NSObject, SNResultsObserving {
    private var analyzer: SNAudioStreamAnalyzer?
    private let queue = DispatchQueue(label: "com.laughcounter.sound-analysis")

    /// Called with a full observation for each analysed window.
    var onObservation: ((LaughObservation) -> Void)?

    // Stems, not whole words: the classifier emits gerunds like "giggling", so
    // "giggle" would miss it — "giggl" matches both "giggle" and "giggling".
    private static let laughKeywords = ["laugh", "giggl", "chuckl", "chortl",
                                        "snicker", "cackl", "guffaw"]
    // "Produced-audio" classes that point at a TV / recording rather than a person
    // in the room: a soundtrack (music, instruments), dialogue (speech, chatter),
    // and a broadcast audience (crowd, applause, cheering). Matched as
    // case-insensitive substrings, so "guitar"/"electric_guitar" both hit "guitar".
    // The strongest of these becomes the episode's `tvSignal` for you-vs-TV attribution.
    private static let tvKeywords = [
        "applause", "crowd", "cheer", "audience", "television", "clapping",
        "music", "speech", "chatter", "singing", "orchestra",
        "drum", "percussion", "instrument", "guitar", "piano", "violin",
        "string", "bassoon", "flute", "trumpet", "didgeridoo", "saxophone",
    ]

    // The analyzer wants monotonically increasing frame positions starting near 0.
    // We anchor those positions (and the wall-clock epoch) to the first buffer of
    // each stream, so window timestamps are real audio times, valid across restarts.
    private var baseSampleTime: AVAudioFramePosition?
    private var startEpoch: Double = 0

    // One log line per stream confirming the analysis pipeline is delivering
    // results after a (re)start — so "it stopped detecting" is diagnosable.
    private var sawFirstResult = false

    func configure(format: AVAudioFormat) throws {
        let analyzer = SNAudioStreamAnalyzer(format: format)
        let request = try SNClassifySoundRequest(classifierIdentifier: .version1)
        try analyzer.add(request, withObserver: self)
        self.analyzer = analyzer
        self.baseSampleTime = nil
    }

    func analyze(_ buffer: AVAudioPCMBuffer, at when: AVAudioTime) {
        queue.async { [weak self] in
            guard let self = self, let analyzer = self.analyzer else { return }
            if self.baseSampleTime == nil {
                self.baseSampleTime = when.sampleTime
                self.startEpoch = Date().timeIntervalSince1970
            }

import AppKit
import Foundation

/// Appends laugh events to a JSONL log under
/// `~/Library/Application Support/LaughCounter/laughs.jsonl`.
///
/// Deliberately greppable. Fields are written in a **fixed
/// order** every line (`start_iso, label, start, end, peak, duration, mean,
/// source`, then `type`/`context` when present) so the log diffs cleanly and is
/// easy to eyeball — `JSONSerialization` can't guarantee key order, so we render
/// the JSON ourselves. Confidence values are rounded (they carry no meaning past a
/// couple of decimals). No audio is stored — only metadata.
final class LaughStore {
    private let directory: URL
    let fileURL: URL

    init() {
        let base = FileManager.default.urls(for: .applicationSupportDirectory,
                                            in: .userDomainMask)[0]
        directory = base.appendingPathComponent("LaughCounter", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory,
                                                 withIntermediateDirectories: true)
        fileURL = directory.appendingPathComponent("laughs.jsonl")
    }

    /// Log a detected laugh.
    func append(_ event: LaughEvent, source: String = "mic", label: String = "auto") {
        var fields: [(String, JSON)] = [
            ("start_iso", .str(Self.iso(event.start))),
            ("label", .str(label)),
            ("start", .num(round3(event.start))),
            ("end", .num(round3(event.end))),
            ("peak", .num(round2(event.peak))),
            ("duration", .num(round2(event.duration))),
            ("mean", .num(round2(event.mean))),
            ("source", .str(source)),
            ("origin", .str(event.origin)),
            ("tv_signal", .num(round2(event.tvSignal))),
            ("origin_reason", .str(event.originReason)),
        ]
        if !event.type.isEmpty {
            fields.append(("type", .str(event.type)))
        }
        if !event.context.isEmpty {
            fields.append(("context", .arr(event.context.map { c in
                JSON.obj([("label", .str(c.label)), ("confidence", .num(round2(c.confidence)))])
            })))
        }
        write(JSON.obj(fields))
    }

    /// Log a laugh you told us we missed. `source` distinguishes the spoken
    /// command (`"voice"`) from a menu/keyboard click (`"button"`).
    func appendMissed(source: String = "voice") {
        let now = Date().timeIntervalSince1970
        // A miss you reported is, by definition, you.
        append(LaughEvent(start: now - 0.5, end: now, duration: 0.5,
                          peak: 0, mean: 0, type: "", context: [],
                          origin: "me", originReason: "you reported it", tvSignal: 0),
               source: source, label: "missed")

